// Reference solution
function traceroute(path, silent, maxTtl) {
  var out = [];
  for (var ttl = 1; ttl <= maxTtl; ttl++) {
    var i = ttl - 1;
    if (i >= path.length) { out.push(ttl + ' *'); continue; }
    out.push(ttl + ' ' + (silent.indexOf(i) >= 0 ? '*' : path[i]));
    if (i === path.length - 1) break;
  }
  return out;
}
